**Gates before launch**

I run four gates before the launch and keep the output of each one. First, I confirm that spe/predictions/r04.yaml and spe/plans/r04.md are committed and unchanged since the predict commit. I check this with `git log` and `git status --porcelain` on both files. Second, I run the grader selftest. grade.py must mark every label correct on an oracle file built from answers.json. It must mark no label correct on an empty file or on a file where every label is wrong. Third, I regrade r03's saved outputs with today's grade.py as a control. Each label accuracy must match the r03 row in spe/prediction-log.md. A mismatch means the grader changed, and I halt the round. Fourth, I launch this script with `dryRun: true` on 2 tickets x 2 configs x 1 trial. I check that the outputs land in spe/evals/runs/r04-dry, that the peek scan finds every transcript, and that the judge returns valid scores. I then replace the placeholder per-call costs in `args.cost` with what the dry run actually cost. After that, I commit the harness as `SPE r04 evaluate (harness)` and launch the full run. The script's Preflight phase repeats the first three checks as a guard, and it halts if any check fails.

**Assumptions to check against r03 before the dry run.** The rules for this trial did not let me read r03-workflow.js, grade.py, or the task files. So these values come in through `args`, and the script halts if they are missing: `trialModel`, `configs.{B,C2}.promptPath/toolsPath` (with `toolNames` optional), `tickets` as `[{id, path}]`, `gradeCmd` containing `{pred}`, and `transcriptDir`. I also had to guess how the trial agent runs the config's tools. That must match whatever r03 did. All dollar costs in `COST` are placeholders. None of them were measured.

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'One SPE round: configs B and C2 on the ticket set, code grader for labels, Opus judge for reply tone, spend cap, peek scan, extra trials for split cells, failure analysis, and a completeness critic.',
  phases: ['Preflight', 'Trials', 'Grade', 'Peek scan', 'Judge', 'Extra trials', 'Analysis'],
}

// The round number is set here once. Every prompt, label, id, and path derives from it.
const ROUND = 4
const pad2 = n => String(n).padStart(2, '0')
const RTAG = `r${pad2(ROUND)}`
const PREV_RTAG = `r${pad2(ROUND - 1)}`

// Plan constants from the approved plan.
const CONFIG_NAMES = ['B', 'C2']
const EXPECTED_TICKETS = 50
const TRIALS_PER_CELL = 5
const SPEND_CAP_USD = 40

const A = typeof args !== 'undefined' && args ? args : {}
const DRY_RUN = A.dryRun === true

// Estimated USD per call. These are placeholders, not measurements. The dry run gate replaces them through args.cost.
const COST = Object.assign(
  { trial: 0.03, judge: 0.02, grade: 0.15, scan: 0.25, preflight: 0.25, analysis: 1.0, critic: 0.75 },
  A.cost || {},
)
const EXTRA_PER_SPLIT_CELL = A.extraPerSplitCell ?? 3
const EXTRA_TOTAL_CAP = A.extraTotalCap ?? 60
const CONCURRENCY = A.concurrency ?? 10
const GRADE_BATCH = A.gradeBatch ?? 25
const JUDGE_MODEL = 'opus'
const WORKER_MODEL = A.workerModel || 'opus'

const PATHS = {
  answers: 'spe/evals/tasks/answers.json',
  judge: 'spe/evals/graders/judge.md',
  failures: 'spe/failures.md',
  predictionLog: 'spe/prediction-log.md',
  prediction: `spe/predictions/${RTAG}.yaml`,
  plan: `spe/plans/${RTAG}.md`,
  runDir: `spe/evals/runs/${RTAG}${DRY_RUN ? '-dry' : ''}`,
  prevRunDir: `spe/evals/runs/${PREV_RTAG}`,
}

// Trials must never touch these. The trial prompt does not name them. The peek scan checks for them.
const FORBIDDEN = [
  'spe/evals/graders/',
  'grade.py',
  'judge.md',
  'answers.json',
  'spe/predictions/',
  'spe/plans/',
  'spe/spec/',
  'spe/prediction-log.md',
  'spe/failures.md',
  'spe/evals/runs/',
  'spe/evals/harness/',
]
const isForbidden = p => FORBIDDEN.some(f => String(p).includes(f))
const isAnswerKey = p => /answers\.json|evals\/graders\/|grade\.py/.test(String(p))

// Small helpers.
const range = (a, b) => (b < a ? [] : Array.from({ length: b - a + 1 }, (_, i) => a + i))
const chunk = (xs, n) => range(0, Math.ceil(xs.length / n) - 1).map(i => xs.slice(i * n, i * n + n))
const nonEmpty = s => typeof s === 'string' && s.trim().length > 0
const r2 = x => Math.round(x * 100) / 100
const r3 = x => Math.round(x * 1000) / 1000
const rate = (xs, f) => (xs.length ? r3(xs.filter(f).length / xs.length) : null)
const fmt = x => (x === null || x === undefined ? 'n/a' : String(x))

function halt(msg) {
  throw new Error(`${RTAG} halt: ${msg}`)
}

// Code checks on the arguments before anything is spent.
if (!A.trialModel) halt('args.trialModel is required. Use the model the previous round used.')
for (const c of CONFIG_NAMES) {
  const cfg = (A.configs || {})[c]
  if (!cfg || !cfg.promptPath || !cfg.toolsPath) halt(`args.configs.${c} needs promptPath and toolsPath.`)
  if (isForbidden(cfg.promptPath) || isForbidden(cfg.toolsPath)) halt(`args.configs.${c} points a trial at a forbidden path.`)
}
if (A.configs.B.toolNames && A.configs.B.toolNames.length !== 6) halt('config B must have 6 tools.')
if (A.configs.C2.toolNames && (A.configs.C2.toolNames.length !== 4 || !A.configs.C2.toolNames.includes('check_status'))) {
  halt('config C2 must have 3 tools plus check_status.')
}
if (!Array.isArray(A.tickets) || A.tickets.some(t => !t || !t.id || !t.path)) halt('args.tickets must be a list of {id, path}.')
if (A.tickets.some(t => isForbidden(t.path))) halt('a ticket path points at a forbidden path.')
if (!DRY_RUN && A.tickets.length !== EXPECTED_TICKETS) halt(`expected ${EXPECTED_TICKETS} tickets, got ${A.tickets.length}.`)
if (typeof A.gradeCmd !== 'string' || !A.gradeCmd.includes('{pred}')) halt('args.gradeCmd must be a shell command containing {pred}.')
if (!A.transcriptDir) halt('args.transcriptDir is required for the peek scan.')

const TICKETS = DRY_RUN ? A.tickets.slice(0, A.dryRunTickets || 2) : A.tickets
const BASE_TRIALS = DRY_RUN ? 1 : TRIALS_PER_CELL
const ticketById = new Map(TICKETS.map(t => [t.id, t]))

// Spend ledger. Every paid call reserves its estimated cost first. A call that would cross the cap is skipped and logged.
const ledger = { cap: SPEND_CAP_USD, committed: 0, skips: [] }
function reserve(usd, what) {
  if (ledger.committed + usd > ledger.cap) {
    ledger.skips.push({ what, usd: r2(usd), committed: r2(ledger.committed) })
    log(`${RTAG} skip ${what}: estimated ${r2(ledger.committed)} + ${r2(usd)} USD would cross the ${ledger.cap} USD cap`)
    return false
  }
  ledger.committed += usd
  return true
}
const PER_TRIAL_USD = COST.trial + COST.judge + COST.grade / GRADE_BATCH
const CLOSEOUT_USD = COST.scan * CONFIG_NAMES.length * 2 + COST.analysis + COST.critic

const flags = { answerKeyExposed: false, graderErrors: 0, scanFailures: [] }

async function call(prompt, opts) {
  try {
    const out = await agent(prompt, opts)
    return { ok: out !== null && out !== undefined, out }
  } catch (e) {
    return { ok: false, error: String((e && e.message) || e) }
  }
}

async function runChunked(thunks) {
  const out = []
  let i = 0
  while (i < thunks.length) {
    const part = await parallel(thunks.slice(i, i + CONCURRENCY))
    out.push(...part)
    i += CONCURRENCY
  }
  return out
}

// Schemas.
const PREFLIGHT_SCHEMA = {
  type: 'object',
  required: ['prediction_committed', 'prediction_unchanged', 'plan_committed', 'selftest', 'control'],
  properties: {
    prediction_committed: { type: 'boolean' },
    prediction_unchanged: { type: 'boolean' },
    plan_committed: { type: 'boolean' },
    selftest: {
      type: 'object',
      required: ['oracle_pass', 'empty_fail', 'wrong_fail'],
      properties: { oracle_pass: { type: 'boolean' }, empty_fail: { type: 'boolean' }, wrong_fail: { type: 'boolean' } },
    },
    control: { type: 'object', required: ['matches'], properties: { matches: { type: 'boolean' }, detail: { type: 'string' } } },
    notes: { type: 'string' },
  },
}
const TRIAL_SCHEMA = {
  type: 'object',
  required: ['trial_id', 'label', 'reply', 'tool_calls', 'files_read'],
  properties: {
    trial_id: { type: 'string' },
    label: {
      type: 'object',
      required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } },
    },
    reply: { type: 'string' },
    tool_calls: {
      type: 'array',
      items: { type: 'object', required: ['tool'], properties: { tool: { type: 'string' }, args: { type: 'object' } } },
    },
    files_read: { type: 'array', items: { type: 'string' } },
  },
}
const GRADE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'category_correct', 'priority_correct'],
        properties: {
          trial_id: { type: 'string' },
          category_correct: { type: 'boolean' },
          priority_correct: { type: 'boolean' },
          raw: { type: 'string' },
          error: { type: 'string' },
        },
      },
    },
  },
}
const SCAN_SCHEMA = {
  type: 'object',
  required: ['peeked', 'missing', 'scanned'],
  properties: {
    peeked: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial_id', 'path', 'evidence'],
        properties: { trial_id: { type: 'string' }, path: { type: 'string' }, evidence: { type: 'string' } },
      },
    },
    missing: { type: 'array', items: { type: 'string' } },
    scanned: { type: 'integer' },
  },
}
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['judge_id', 'tone_pass', 'score', 'reason'],
  properties: {
    judge_id: { type: 'string' },
    tone_pass: { type: 'boolean' },
    score: { type: 'integer', minimum: 1, maximum: 5 },
    reason: { type: 'string' },
  },
}
const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['types'],
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'name', 'kind', 'what', 'how_to_spot', 'trial_ids', 'fix'],
        properties: {
          id: { type: 'string', description: 'An existing F-number from spe/failures.md, or NEW-1, NEW-2, and so on' },
          name: { type: 'string' },
          kind: { type: 'string', description: 'model, prompt, tool, task, grader, or harness' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          trial_ids: { type: 'array', items: { type: 'string' } },
          count_by_config: { type: 'object' },
          fix: { type: 'string' },
        },
      },
    },
    notes: { type: 'string' },
  },
}
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } } },
}

// Prompts.
function preflightPrompt() {
  return [
    `You check the gates for SPE round ${ROUND} before any trial runs.`,
    `Do not edit any file. You may create temporary files under ${PATHS.runDir}/preflight/ only.`,
    '',
    `1. Prediction lock. Run git log -1 --format="%H %cI" -- ${PATHS.prediction} and the same for ${PATHS.plan}. Each must print a commit.`,
    `   Run git status --porcelain -- ${PATHS.prediction} ${PATHS.plan}. It must print nothing.`,
    '   Report prediction_committed, plan_committed, and prediction_unchanged.',
    `2. Grader selftest. Read ${PATHS.answers}. Build per-ticket prediction files in the format {"ticket_id": ..., "label": {"category": ..., "priority": ...}}:`,
    '   an oracle set with the expected label for every ticket, one empty file with an empty label, and a wrong set where every category and every priority is changed to a different valid value.',
    `   Grade each file with this command, with the file path in place of {pred}: ${A.gradeCmd}`,
    '   oracle_pass is true only if every oracle label scores correct on both fields. empty_fail and wrong_fail are true only if no field scores correct.',
    `3. Control. Regrade the saved trial outputs in ${PATHS.prevRunDir} with the same command.`,
    `   Compare category, priority, and label accuracy per config with the ${PREV_RTAG} rows in ${PATHS.predictionLog}.`,
    '   matches is true only if every number is the same. Put every difference in detail.',
    '',
    'For any check that fails, quote the exact command output in notes.',
  ].join('\n')
}

function trialPrompt(cfg, ticket, trialId) {
  return [
    `SPE-TRIAL-ID: ${trialId}`,
    '',
    'You are the customer support agent under test.',
    `1. Read your system prompt from ${cfg.promptPath}. Follow it exactly for the rest of this task.`,
    `2. Read your tool definitions from ${cfg.toolsPath}. Use these tools the way that file describes. Do not use any tool it does not define.`,
    `3. Read the customer ticket at ${ticket.path}.`,
    'Handle the ticket the way the system prompt says. Choose a category and a priority for it. Write the reply you would send the customer.',
    'Read only the three files named above. Do not open, list, or search any other file or folder.',
    'Return trial_id exactly as it appears on the first line. List every tool call you made in tool_calls, in order. List every file path you opened in files_read.',
  ].join('\n')
}

function gradePrompt(items) {
  return [
    `You run the code grader for SPE round ${ROUND}. You do not judge anything yourself.`,
    `Do not edit the grader, the answers file, or any file outside ${PATHS.runDir}.`,
    'For each trial in the list below:',
    `1. Write the trial object, exactly as given, to ${PATHS.runDir}/<trial_id>.json. Create the folder if it does not exist.`,
    `2. Run this command with that file path in place of {pred}: ${A.gradeCmd}`,
    '3. Report category_correct and priority_correct exactly as the grader printed them. Copy the grader output line into raw.',
    'If the grader exits with an error, put the exact error text in error and set both booleans to false.',
    'Return one result for every trial. Do not skip any trial.',
    '',
    'Trials:',
    JSON.stringify(items, null, 1),
  ].join('\n')
}

function scanPrompt(ids) {
  return [
    `You check SPE round ${ROUND} trials for peeking. Do not edit any file.`,
    `Trial transcripts are under ${A.transcriptDir}. Each trial transcript contains the line "SPE-TRIAL-ID: <id>" near the start.`,
    'For each trial id below, find every transcript that contains it. List every path the trial read, listed, searched, or passed to a shell command.',
    `Flag the trial if any of those paths contains one of these strings: ${FORBIDDEN.join(', ')}`,
    'For each flagged trial, give the path and quote the exact tool call as evidence.',
    'Put every trial id that has no transcript in missing. Set scanned to the number of transcripts you checked.',
    '',
    'Trial ids:',
    ids.join('\n'),
  ].join('\n')
}

function judgePrompt(r) {
  return [
    'You grade the tone of one customer support reply.',
    `Read the rubric at ${PATHS.judge} and apply it exactly. Read the customer ticket at ${r.ticket_path} for context.`,
    'Judge tone only, as the rubric defines it. Do not judge the category, the priority, or the facts in the reply.',
    `Return judge_id exactly as: ${r.judge_id}`,
    '',
    'The reply to grade is between the markers.',
    '<<<REPLY',
    r.reply,
    'REPLY>>>',
  ].join('\n')
}

// Code checks on one trial output. These run before any grader or judge.
function codeCheck(rec, out, cfg) {
  const selfPeeks = rec.files_read.filter(isForbidden)
  if (selfPeeks.length) {
    rec.status = 'void'
    rec.void_reason = `self-reported read of ${selfPeeks.join(', ')}`
    if (selfPeeks.some(isAnswerKey)) flags.answerKeyExposed = true
    return
  }
  if (out.trial_id !== rec.trial_id) rec.problems.push('trial_id mismatch')
  const lab = out.label || {}
  if (!nonEmpty(lab.category)) rec.problems.push('missing category')
  if (!nonEmpty(lab.priority)) rec.problems.push('missing priority')
  if (Array.isArray(cfg.toolNames)) {
    for (const tc of rec.tool_calls) {
      if (!tc || !cfg.toolNames.includes(tc.tool)) rec.problems.push(`tool not in config: ${tc && tc.tool}`)
    }
  }
  if (!nonEmpty(out.reply)) {
    rec.tone_pass = false
    rec.tone_reason = 'empty reply (code check)'
  }
  const labelBroken = rec.problems.some(p => p.startsWith('missing') || p === 'trial_id mismatch')
  if (labelBroken) {
    rec.status = 'malformed'
    rec.category_correct = false
    rec.priority_correct = false
    rec.label_pass = false
  } else {
    rec.status = 'ok'
  }
}

async function runTrial(config, ticket, t, kind) {
  const trialId = `${RTAG}-${config}-${ticket.id}-t${t}`
  const rec = { trial_id: trialId, config, ticket_id: ticket.id, ticket_path: ticket.path, t, kind, status: 'pending', problems: [] }
  if (!reserve(PER_TRIAL_USD, trialId)) {
    rec.status = 'skipped_budget'
    return rec
  }
  const cfg = A.configs[config]
  const opts = { label: trialId, phase: kind === 'extra' ? 'Extra trials' : 'Trials', schema: TRIAL_SCHEMA, model: A.trialModel }
  let res = await call(trialPrompt(cfg, ticket, trialId), opts)
  if (!res.ok && reserve(COST.trial, `${trialId} retry`)) {
    res = await call(trialPrompt(cfg, ticket, trialId), opts)
  }
  if (!res.ok) {
    rec.status = 'error'
    rec.error = res.error || 'no output'
    return rec
  }
  const out = res.out
  rec.label = out.label
  rec.reply = out.reply
  rec.tool_calls = Array.isArray(out.tool_calls) ? out.tool_calls : []
  rec.files_read = Array.isArray(out.files_read) ? out.files_read : []
  codeCheck(rec, out, cfg)
  return rec
}

async function gradeBatch(batch, tag, phaseName) {
  const items = batch.map(r => ({
    trial_id: r.trial_id,
    config: r.config,
    ticket_id: r.ticket_id,
    label: r.label,
    reply: r.reply,
    tool_calls: r.tool_calls,
  }))
  const res = await call(gradePrompt(items), { label: `${RTAG}-grade-${tag}`, phase: phaseName, schema: GRADE_SCHEMA, model: WORKER_MODEL })
  const ids = new Set(batch.map(r => r.trial_id))
  const got = new Map()
  if (res.ok && Array.isArray(res.out.results)) {
    for (const g of res.out.results) {
      if (g && ids.has(g.trial_id) && !got.has(g.trial_id)) got.set(g.trial_id, g)
    }
  }
  return got
}

async function gradeAll(recs, phaseName, tagPrefix) {
  const todo = recs.filter(r => r.status === 'ok' && r.label_pass === undefined)
  const batches = chunk(todo, GRADE_BATCH)
  await runChunked(batches.map((b, i) => async () => {
    const tag = `${tagPrefix}-${i + 1}`
    const got = await gradeBatch(b, tag, phaseName)
    const missing = b.filter(r => !got.has(r.trial_id))
    if (missing.length && reserve(COST.grade, `grade ${tag} retry`)) {
      const again = await gradeBatch(missing, `${tag}-retry`, phaseName)
      for (const [k, v] of again) got.set(k, v)
    }
    for (const r of b) {
      const g = got.get(r.trial_id)
      if (!g) {
        r.status = 'error'
        r.error = 'grader returned no result'
      } else if (nonEmpty(g.error)) {
        r.status = 'error'
        r.error = `grader error: ${g.error}`
        r.grader_error = true
        flags.graderErrors += 1
      } else {
        r.category_correct = g.category_correct === true
        r.priority_correct = g.priority_correct === true
        r.label_pass = r.category_correct && r.priority_correct
        r.grader_raw = g.raw || ''
      }
    }
  }))
}

// The scan cost comes from the close-out reserve taken at the start.
async function peekScan(recs, phaseName, tagPrefix) {
  const live = recs.filter(r => r.status !== 'skipped_budget' && r.status !== 'void' && r.status !== 'pending')
  const groups = CONFIG_NAMES.map(c => live.filter(r => r.config === c)).filter(xs => xs.length)
  const results = await parallel(groups.map(xs => async () => {
    const ids = xs.map(r => r.trial_id)
    const res = await call(scanPrompt(ids), { label: `${RTAG}-scan-${tagPrefix}-${xs[0].config}`, phase: phaseName, schema: SCAN_SCHEMA, model: WORKER_MODEL })
    return { ids: new Set(ids), res }
  }))
  for (const { ids, res } of results) {
    const mine = live.filter(r => ids.has(r.trial_id))
    if (!res.ok) {
      flags.scanFailures.push(`${tagPrefix}: ${res.error || 'no output'}`)
      for (const r of mine) r.peek_unverified = true
      continue
    }
    const peeked = new Map(res.out.peeked.filter(p => ids.has(p.trial_id)).map(p => [p.trial_id, p]))
    const missing = new Set(res.out.missing)
    for (const r of mine) {
      const p = peeked.get(r.trial_id)
      if (p) {
        r.status = 'void'
        r.void_reason = `transcript shows ${p.path}: ${p.evidence}`
        if (isAnswerKey(p.path)) flags.answerKeyExposed = true
      }
      if (missing.has(r.trial_id)) r.peek_unverified = true
    }
  }
}

// The judge cost is reserved inside each trial. The judge never sees the config name.
let judgeCounter = 0
async function judgeAll(recs, phaseName) {
  const todo = recs.filter(r => r.status === 'ok' && r.tone_pass === undefined)
  for (const r of todo) {
    judgeCounter += 1
    r.judge_id = `${RTAG}-J${judgeCounter}`
  }
  await runChunked(todo.map(r => async () => {
    const res = await call(judgePrompt(r), { label: r.judge_id, phase: phaseName, schema: JUDGE_SCHEMA, model: JUDGE_MODEL })
    if (!res.ok || res.out.judge_id !== r.judge_id) {
      r.tone_error = res.ok ? 'judge_id mismatch' : res.error || 'no output'
      return
    }
    r.tone_pass = res.out.tone_pass === true
    r.tone_score = res.out.score
    r.tone_reason = res.out.reason
  }))
}

const isScored = r => (r.status === 'ok' || r.status === 'malformed') && typeof r.label_pass === 'boolean'

function splitCells(recs) {
  const cells = new Map()
  for (const r of recs) {
    if (r.kind !== 'base' || !isScored(r)) continue
    const k = `${r.config}|${r.ticket_id}`
    if (!cells.has(k)) cells.set(k, { config: r.config, ticket_id: r.ticket_id, pass: 0, fail: 0 })
    const c = cells.get(k)
    if (r.label_pass) c.pass += 1
    else c.fail += 1
  }
  return [...cells.values()].filter(c => c.pass > 0 && c.fail > 0)
}

function summarize(recs) {
  const out = {}
  for (const c of CONFIG_NAMES) {
    const rs = recs.filter(r => r.config === c)
    const scored = rs.filter(isScored)
    const judged = scored.filter(r => typeof r.tone_pass === 'boolean')
    const count = s => rs.filter(r => r.status === s).length
    const perTicket = new Map()
    for (const r of scored) {
      const prev = perTicket.get(r.ticket_id)
      perTicket.set(r.ticket_id, prev === undefined ? r.label_pass : prev && r.label_pass)
    }
    const allPass = Array.from(perTicket.values()).filter(Boolean).length
    out[c] = {
      trials_scored: scored.length,
      malformed: count('malformed'),
      voided: count('void'),
      errors: count('error'),
      skipped_budget: count('skipped_budget'),
      peek_unverified: rs.filter(r => r.peek_unverified).length,
      category_acc: rate(scored, r => r.category_correct === true),
      priority_acc: rate(scored, r => r.priority_correct === true),
      label_acc: rate(scored, r => r.label_pass === true),
      tone_judged: judged.length,
      tone_errors: scored.filter(r => r.tone_error).length,
      tone_pass_rate: rate(judged, r => r.tone_pass === true),
      mean_tool_calls: scored.length ? r2(scored.reduce((s, r) => s + (r.tool_calls || []).length, 0) / scored.length) : null,
      check_status_use_rate: rate(scored, r => (r.tool_calls || []).some(tc => tc && tc.tool === 'check_status')),
      tickets_all_label_pass: perTicket.size ? r3(allPass / perTicket.size) : null,
    }
  }
  return out
}

// ---- Preflight ----
phase('Preflight')
if (!reserve(COST.preflight, 'preflight')) halt('the cap cannot cover preflight.')
if (!reserve(CLOSEOUT_USD, 'close-out reserve')) halt('the cap cannot cover the peek scans, failure analysis, and critic.')
const pre = await call(preflightPrompt(), { label: `${RTAG}-preflight`, phase: 'Preflight', schema: PREFLIGHT_SCHEMA, model: WORKER_MODEL })
if (!pre.ok) halt(`preflight agent failed: ${pre.error || 'no output'}`)
const gates = {
  prediction_committed: pre.out.prediction_committed,
  prediction_unchanged: pre.out.prediction_unchanged,
  plan_committed: pre.out.plan_committed,
  oracle_pass: pre.out.selftest && pre.out.selftest.oracle_pass,
  empty_fail: pre.out.selftest && pre.out.selftest.empty_fail,
  wrong_fail: pre.out.selftest && pre.out.selftest.wrong_fail,
  control_match: pre.out.control && pre.out.control.matches,
}
const failedGates = Object.entries(gates).filter(([, v]) => v !== true).map(([k]) => k)
if (failedGates.length) halt(`preflight gates failed: ${failedGates.join(', ')}. ${pre.out.notes || ''} ${(pre.out.control && pre.out.control.detail) || ''}`)
log(`${RTAG} preflight passed${DRY_RUN ? ' (dry run)' : ''}. Estimated committed spend ${r2(ledger.committed)} of ${ledger.cap} USD.`)

// ---- Trials ----
// Order is trial index, then ticket, then config. If the cap cuts the run short, both configs lose the same cells.
phase('Trials')
const baseThunks = []
for (const t of range(1, BASE_TRIALS)) {
  for (const ticket of TICKETS) {
    for (const config of CONFIG_NAMES) baseThunks.push(() => runTrial(config, ticket, t, 'base'))
  }
}
const baseRecs = await runChunked(baseThunks)
log(`${RTAG} base trials: ${baseRecs.length} planned, ${baseRecs.filter(r => r.status === 'skipped_budget').length} skipped for budget, ${baseRecs.filter(r => r.status === 'error').length} errors.`)

// ---- Grade ----
phase('Grade')
await gradeAll(baseRecs, 'Grade', 'base')
log(`${RTAG} graded base trials. Grader errors so far: ${flags.graderErrors}.`)

// ---- Peek scan ----
phase('Peek scan')
await peekScan(baseRecs, 'Peek scan', 'base')
log(`${RTAG} peek scan voided ${baseRecs.filter(r => r.status === 'void').length} base trials. Answer key exposed: ${flags.answerKeyExposed}.`)

// ---- Judge ----
phase('Judge')
await judgeAll(baseRecs, 'Judge')
log(`${RTAG} judged base replies. Estimated committed spend ${r2(ledger.committed)} USD.`)

// ---- Extra trials for split cells ----
phase('Extra trials')
const halts = []
if (flags.answerKeyExposed) halts.push('A trial read the answer key or a grader file.')
if (flags.graderErrors > 0) halts.push(`The grader errored on ${flags.graderErrors} trials.`)
const split = splitCells(baseRecs)
let extraRecs = []
if (DRY_RUN) {
  log(`${RTAG} dry run: extra trials skipped.`)
} else if (halts.length) {
  log(`${RTAG} extra trials skipped because of a halt condition: ${halts.join(' ')}`)
} else {
  const extraPlan = []
  for (const k of range(1, EXTRA_PER_SPLIT_CELL)) {
    for (const c of split) {
      if (extraPlan.length < EXTRA_TOTAL_CAP) extraPlan.push({ config: c.config, ticket: ticketById.get(c.ticket_id), t: BASE_TRIALS + k })
    }
  }
  log(`${RTAG} ${split.length} split cells. Planning ${extraPlan.length} extra trials (cap ${EXTRA_PER_SPLIT_CELL} per cell, ${EXTRA_TOTAL_CAP} total).`)
  extraRecs = await runChunked(extraPlan.map(p => () => runTrial(p.config, p.ticket, p.t, 'extra')))
  await gradeAll(extraRecs, 'Extra trials', 'extra')
  await peekScan(extraRecs, 'Extra trials', 'extra')
  await judgeAll(extraRecs, 'Extra trials')
  if (flags.answerKeyExposed && !halts.some(h => h.includes('answer key'))) halts.push('A trial read the answer key or a grader file.')
  if (flags.graderErrors > 0 && !halts.some(h => h.includes('grader errored'))) halts.push(`The grader errored on ${flags.graderErrors} trials.`)
}
if (ledger.skips.length) halts.push(`The spend cap skipped ${ledger.skips.length} calls.`)

// ---- Analysis ----
phase('Analysis')
const all = baseRecs.concat(extraRecs)
const metricsBase = summarize(baseRecs)
const metricsAll = summarize(all)

const cellsShort = []
for (const config of CONFIG_NAMES) {
  for (const ticket of TICKETS) {
    const n = baseRecs.filter(r => r.config === config && r.ticket_id === ticket.id && isScored(r)).length
    if (n < BASE_TRIALS) cellsShort.push({ config, ticket_id: ticket.id, scored: n })
  }
}

const failing = all
  .filter(r => isScored(r) && (r.label_pass === false || r.tone_pass === false))
  .map(r => ({
    trial_id: r.trial_id,
    config: r.config,
    ticket_id: r.ticket_id,
    kind: r.kind,
    label: r.label,
    category_correct: r.category_correct,
    priority_correct: r.priority_correct,
    tone_pass: r.tone_pass,
    tone_reason: r.tone_reason,
    problems: r.problems,
    tools: (r.tool_calls || []).map(tc => tc && tc.tool),
  }))
const harnessIssues = all
  .filter(r => r.status === 'void' || r.status === 'error' || r.tone_error)
  .map(r => ({ trial_id: r.trial_id, status: r.status, reason: r.void_reason || r.error || r.tone_error }))

const analysisRes = await call(
  [
    `You do failure analysis for SPE round ${ROUND}. Do not edit any file.`,
    `Read ${PATHS.failures} for the existing failure types and their F-numbers.`,
    `You may read raw trial outputs in ${PATHS.runDir} and the expected labels in ${PATHS.answers}.`,
    'Assign every failing trial below to exactly one failure type. Reuse an existing F-number when it fits. Otherwise propose a new type with id NEW-1, NEW-2, and so on.',
    'Treat voided trials, grader errors, and judge errors as harness failures. A grader bug found now is a failure type too.',
    'Give count_by_config for each type.',
    '',
    'Failing trials:',
    JSON.stringify(failing, null, 1),
    '',
    'Harness issues:',
    JSON.stringify(harnessIssues, null, 1),
  ].join('\n'),
  { label: `${RTAG}-failure-analysis`, phase: 'Analysis', schema: ANALYSIS_SCHEMA, model: WORKER_MODEL },
)
const analysis = analysisRes.ok ? analysisRes.out : { types: [], notes: `failure analysis failed: ${analysisRes.error || 'no output'}` }
const assigned = new Set()
for (const ty of analysis.types || []) for (const id of ty.trial_ids || []) assigned.add(id)
const unassigned = failing.map(f => f.trial_id).filter(id => !assigned.has(id))

const criticInput = {
  round: ROUND,
  dry_run: DRY_RUN,
  configs: CONFIG_NAMES,
  tickets: TICKETS.length,
  base_trials_per_cell: BASE_TRIALS,
  metrics_base: metricsBase,
  cells_short: cellsShort,
  split_cells: split.length,
  extra_trials: extraRecs.length,
  budget_skips: ledger.skips.length,
  grader_errors: flags.graderErrors,
  scan_failures: flags.scanFailures,
  answer_key_exposed: flags.answerKeyExposed,
  failing_trials: failing.length,
  unassigned_failures: unassigned,
  halts,
}
const criticRes = await call(
  [
    `You are the completeness critic for SPE round ${ROUND}. Do not edit any file. Do not read the saved prediction.`,
    'Decide whether these results are complete enough to compare with the round prediction.',
    'Check that every cell has its full base trials or a logged reason, that every skip, void, and error is counted, that the peek scan covered every trial, that the judge ran on every scorable reply, and that every failing trial has a failure type.',
    'List each gap as one plain sentence. Set complete to false if any gap changes a headline number.',
    '',
    JSON.stringify(criticInput, null, 1),
  ].join('\n'),
  { label: `${RTAG}-critic`, phase: 'Analysis', schema: CRITIC_SCHEMA, model: WORKER_MODEL },
)
const critic = criticRes.ok ? criticRes.out : { complete: false, gaps: [`critic failed: ${criticRes.error || 'no output'}`] }

const headline =
  `${RTAG}${DRY_RUN ? ' dry run' : ''}: label accuracy B ${fmt(metricsBase.B.label_acc)}, C2 ${fmt(metricsBase.C2.label_acc)}. ` +
  `Tone pass B ${fmt(metricsBase.B.tone_pass_rate)}, C2 ${fmt(metricsBase.C2.tone_pass_rate)}.` +
  (halts.length ? ` HALT: ${halts.join(' ')}` : '')
log(headline)

return {
  round: ROUND,
  tag: RTAG,
  dry_run: DRY_RUN,
  headline,
  halts,
  gates,
  spend: { cap_usd: ledger.cap, estimated_committed_usd: r2(ledger.committed), note: 'Estimates from args.cost. Read the measured spend from the Workflow usage.' },
  skips: ledger.skips,
  metrics_base: metricsBase,
  metrics_all: metricsAll,
  metrics_note: 'Compare predictions with metrics_base. metrics_all adds the extra trials, which over-weight split cells.',
  split_cells: split,
  cells_short: cellsShort,
  voids: all.filter(r => r.status === 'void').map(r => ({ trial_id: r.trial_id, reason: r.void_reason })),
  peek_unverified: all.filter(r => r.peek_unverified).map(r => r.trial_id),
  scan_failures: flags.scanFailures,
  grader_errors: flags.graderErrors,
  failure_analysis: analysis,
  unassigned_failures: unassigned,
  critic,
  run_dir: PATHS.runDir,
  trials: all,
}
